var out=[];doc.pages.filter(function(p){return /^Proto macOS (Light|Dark)$/.test(p.name);}).forEach(function(p){p.layers.filter(function(s){return /^Screen\/macos\/(Light|Dark)\/Clean\/settings/.test(s.name);}).forEach(function(s){var col=s.layers.find(function(l){return l.name==='content-col';});var tb=col.layers.find(function(l){return l.name==='toolbar';});var dt=col.layers.find(function(l){return l.name==='main';}).layers.find(function(l){return l.name==='settings-split';});var nav=dt.layers.find(function(l){return l.name==='categories';});var detail=dt.layers.find(function(l){return l.name==='settings-detail';});var sh=s.layers.find(function(l){return l.name==='plan-sheet';});var bad=[];function scan(l){if(/^link:/.test(l.name))l.name=l.name.replace(/ \d+$/,'');if(l.name==='form:Quiet hours'){l.name='link:settings-notifications';}if(l.type==='Text'&&/^(Lorem|Sample|Synthetic|Setup incomplete)/.test(l.text))bad.push(l.text);(l.layers||[]).forEach(scan);}scan(s);out.push({id:s.name.split('/').pop(),app:p.name,frame:s.id,size:[s.frame.width,s.frame.height],sidebar:s.layers.find(function(l){return l.name==='sidebar';}).frame.width,toolbar:tb.frame.height,categories:nav.frame.width,categoryCount:nav.layers.filter(function(l){return /^link:settings-/.test(l.name);}).length,headings:detail.layers.filter(function(l){return l.name==='detail-heading';}).length,sheet:sh?{x:sh.frame.x,y:sh.frame.y,w:sh.frame.width,radii:sh.style.corners.radii}:null,bad:bad});});});console.log(JSON.stringify(out));